float avg_fuel(int tanks[], int n) {
    int sum = 0;
    for (int i = 0; i < n; i++) {
        sum += tanks[i];
    }
    return (float)sum / n;
}

float avg_fuel(int tanks[], int n) {
    int sum = 0;
    int i = 0;
    while (i < n) {
        sum = sum + tanks[i];
        i++;
    }
    return sum / (float)n;
}

float avg_fuel(int tanks[], int n) {
    int sum = 0;
    int i;
    for (i = n - 1; i >= 0; i--) {
        sum += tanks[i];
    }
    return (float)sum / (float)n;
}

